fn solve(s: &Vec<char>) -> Vec<char> {
    // Create a new vector by cloning the input
    let mut result = s.clone();

    // Check the last character to decide whether to append "es" or "s"
    if let Some(&last_char) = s.last() {
        if last_char == 's' {
            result.push('e');
            result.push('s');
        } else {
            result.push('s');
        }
    }

    result
}

